#[test]
fn width_floor_trips_the_banner_below_the_floor_only() {
    let _home = crate::testutil::HomeSandbox::new();
    use super::{BannerSeverity, update_banner};
    let mut app = bare_app();
    // Below the floor on width alone (height is roomy): the banner still
    // fires, with the same copy as the height-only compact banner.
    app.update_compact(20, 33);
    assert!(app.below_width_floor);
    assert!(!app.compact, "height 20 is not compact");
    update_banner(&mut app);
    let banner = app.banner.as_ref().expect("width-floor banner present");
    assert_eq!(banner.severity, BannerSeverity::Warning);
    assert_eq!(
        banner.message,
        "terminal too small · enlarge for full layout"
    );

    // At the floor it clears; the layout still draws, no banner.
    app.update_compact(20, 34);
    assert!(!app.below_width_floor);
    update_banner(&mut app);
    assert!(app.banner.is_none(), "banner self-clears at the floor");
}

#[test]
fn height_and_width_below_floor_render_one_banner() {
    let _home = crate::testutil::HomeSandbox::new();
    use super::{BannerSeverity, update_banner};
    let mut app = bare_app();
    app.update_compact(13, 33); // both height < 14 and width < 34
    assert!(app.compact && app.below_width_floor);
    update_banner(&mut app);
    let banner = app.banner.as_ref().expect("one banner");
    assert_eq!(banner.severity, BannerSeverity::Warning);
    assert_eq!(
        banner.message,
        "terminal too small · enlarge for full layout"
    );

    // A real frame, not just state: the banner row renders once, ` ! ` kept,
    // the message fitted (ending in `…`) instead of clipping without a mark.
    use ratatui::{Terminal, backend::TestBackend};
    let mut term = Terminal::new(TestBackend::new(33, 13)).unwrap();
    term.draw(|f| crate::tui::render::draw(f, &app)).unwrap();
    let rows = crate::testutil::buffer_rows(term.backend().buffer());
    let banner_rows: Vec<&str> = rows
        .iter()
        .map(String::as_str)
        .filter(|r| r.contains("terminal too small"))
        .collect();
    assert_eq!(banner_rows.len(), 1, "exactly one banner row: {rows:?}");
    assert_eq!(banner_rows[0], " ! warning: terminal too small ·…");
}

// ── global config tab ────────────────────────────────────────────────────

use super::theme::{self, Tier};
use super::{GLOBAL_CONFIG_ROWS, GlobalConfigRow, KeyCode, Tab};

use crate::testutil::{TierSandbox, key};

// ── walk order (issue #86): the Config-tab cycle handler ────────────────────

#[test]
fn walk_order_space_cycles_and_persists() {
    let _home = crate::testutil::HomeSandbox::new();
    let mut app = bare_app();
    app.tab = Tab::Config;
    app.global_config_cursor = GLOBAL_CONFIG_ROWS
        .iter()
        .position(|r| *r == GlobalConfigRow::WalkOrder)
        .unwrap();
    assert_eq!(
        app.config().state.walk_order(),
        crate::profile::WalkOrder::Chain,
        "chain by default"
    );

    super::handle_global_config_key(&mut app, key(KeyCode::Char(' ')));
    assert_eq!(
        app.config().state.walk_order(),
        crate::profile::WalkOrder::SoonestWeeklyReset,
        "space cycles to soonest weekly reset"
    );

    // Persisted to profiles.toml, not just the in-memory config — reload it
    // fresh, the way a relaunch would pick up the value.
    let reloaded: crate::profile::AppState = toml::from_str(
        &std::fs::read_to_string(
            crate::profile::tollgate_dir()
                .unwrap()
                .join("profiles.toml"),
        )
        .expect("read profiles.toml"),
    )
    .expect("parse profiles.toml");
    assert_eq!(
        reloaded.walk_order(),
        crate::profile::WalkOrder::SoonestWeeklyReset,
        "the cycled value persists to disk"
    );

    super::handle_global_config_key(&mut app, key(KeyCode::Char(' ')));
    assert_eq!(
        app.config().state.walk_order(),
        crate::profile::WalkOrder::MostWeeklyHeadroom,
        "space cycles on to most weekly headroom"
    );
    let reloaded: crate::profile::AppState = toml::from_str(
        &std::fs::read_to_string(
            crate::profile::tollgate_dir()
                .unwrap()
                .join("profiles.toml"),
        )
        .expect("read profiles.toml"),
    )
    .expect("parse profiles.toml");
    assert_eq!(
        reloaded.walk_order(),
        crate::profile::WalkOrder::MostWeeklyHeadroom,
        "the third value persists to disk too"
    );

    super::handle_global_config_key(&mut app, key(KeyCode::Char(' ')));
    assert_eq!(
        app.config().state.walk_order(),
        crate::profile::WalkOrder::Chain,
        "space cycles back to chain"
    );
}

#[test]
fn theme_set_tier_round_trips() {
    // The pin's own store is the first leg; the guard exists so the last leg
    // does not outlive this test.
    let _tier = TierSandbox::new(Tier::Full);
    assert_eq!(theme::tier(), Tier::Full);
    theme::set_tier(Tier::Compatible);
    assert_eq!(theme::tier(), Tier::Compatible);
    theme::set_tier(Tier::Full);
    assert_eq!(theme::tier(), Tier::Full);
}

/// A tier pin is a claim on the thread that installed it; the
/// `PhantomData<*const ()>` field is the whole of what prevents the move.
#[test]
fn a_tier_sandbox_guard_cannot_be_carried_to_another_thread() {
    use crate::testutil::{NotSend as _, Probe};

    assert!(
        !Probe::<TierSandbox>::is_send(),
        "a pin that can cross threads restores the wrong thread's tier"
    );
}

/// The tier must be per-thread under `cargo test` (one process, many threads):
/// a `TierSandbox` on one test thread may never change what a sandbox-less
/// sibling thread reads. Bounded handshake so a regression fails by assertion,
/// never by hang.
#[test]
fn a_thread_without_a_sandbox_reads_full_not_a_siblings_compatible_pin() {
    let home = crate::testutil::HomeSandbox::new();
    let _env = crate::testutil::EnvPin::new(&home, &[("COLORTERM", None)]);
    assert_eq!(
        theme::tier_override(),
        None,
        "no pin is set, so the tier is the fixed test default, not an ambient read"
    );
    assert_eq!(
        theme::tier(),
        Tier::Full,
        "an unset tier reads the fixed Full default"
    );
    let (pinned_tx, pinned_rx) = std::sync::mpsc::channel();
    let (release_tx, release_rx) = std::sync::mpsc::channel();
    let sibling = std::thread::spawn(move || {
        let _pin = TierSandbox::new(Tier::Compatible);
        pinned_tx.send(()).unwrap();
        let _ = release_rx.recv();
    });
    pinned_rx
        .recv_timeout(std::time::Duration::from_secs(10))
        .expect("the sibling pinned Compatible");
    assert_eq!(
        theme::danger_color(),
        ratatui::style::Color::Rgb(243, 139, 168),
        "a sandbox-less thread reads the fixed Full default, never a sibling's pin"
    );
    release_tx.send(()).unwrap();
    sibling.join().unwrap();
}

