// ── Overview `m`: move a live session (hot-swap spec §2.2) ───────────────────

/// Hot-swap spec test 67: `m` on an Overview row opens the move modal over the
/// live claude sessions (each named with the member it is served by), and ⏎
/// hands the pick to the shared session request core on a worker. An
/// api-key session commits and the drain toasts `swapping…`; a relaunch-only
/// session toasts the terminal command, and nothing is relaunched. With no
/// live session, `m` toasts instead of opening an empty modal.
#[test]
fn m_moves_a_live_session_through_the_request_core() {
    use super::{Modal, MoveCandidate, drain_session_moves, handle_key, join_test_workers};
    use crate::testutil::{api_key_profile, key, write_api_key_profile};
    use ratatui::crossterm::event::KeyCode;
    use std::time::Duration;
    const OR: &str = "https://openrouter.ai/api";

    let _home = crate::testutil::HomeSandbox::new();
    let launch = api_key_profile("tm-a", OR, "sk-a");
    write_api_key_profile(&launch);
    write_api_key_profile(&api_key_profile("tm-b", OR, "sk-b"));
    let config = crate::profile::load_config().expect("load config");
    let target_idx = config
        .profiles
        .iter()
        .position(|p| p.name.as_str() == "tm-b")
        .expect("tm-b is on the roster");
    let mut app = super::App::new(config);
    app.modals.clear();
    app.profile_cursor.set(target_idx);
    app.overview_cursor = target_idx;
    let last_toast = |app: &super::App| {
        app.toasts
            .back()
            .map(|t| t.body.clone())
            .unwrap_or_default()
    };

    // Nothing live: a toast, no modal.
    handle_key(&mut app, key(KeyCode::Char('m')));
    assert!(app.modals.is_empty(), "no empty modal");
    assert_eq!(last_toast(&app), "no live claude session to move");

    let row = crate::testutil::live_row("4242-0", "tm-a").with_executor(
        crate::hot_swap::Executor::ApiKey,
        crate::hot_swap::LaunchClass::of(&launch, true),
    );
    crate::live_sessions::register(&row).expect("register");
    let _markers: Vec<std::fs::File> = ["tm-a", "tm-b"]
        .iter()
        .map(|p| {
            crate::runtime::hold_session_row_marker(
                &crate::profile::ProfileName::from(*p),
                false,
                "4242-0",
            )
            .expect("marker")
        })
        .collect();

    handle_key(&mut app, key(KeyCode::Char('m')));
    match app.modals.last() {
        Some(Modal::MoveSession(form)) => {
            assert_eq!(form.target, "tm-b");
            assert_eq!(
                form.sessions,
                [MoveCandidate {
                    sid: "4242-0".to_string(),
                    now_on: "tm-a".to_string(),
                    executor: "api_key",
                    state: crate::hot_swap::SwapState::Served,
                }]
            );
        }
        other => panic!("the move modal is open: {other:?}"),
    }

    // The session's own executor, standing in: commit the intent once it lands.
    let session = std::thread::spawn(|| {
        let deadline = std::time::Instant::now() + Duration::from_secs(5);
        while std::time::Instant::now() < deadline {
            if let Some(intended) =
                crate::live_sessions::get("4242-0").and_then(|r| r.intended_member)
            {
                crate::live_sessions::update_as_session("4242-0", |f| {
                    f.set_current_member(intended);
                    f.bump_key_generation();
                    f.set_committed_at(crate::usage::now_ms());
                })
                .expect("commit");
                return;
            }
            std::thread::sleep(Duration::from_millis(5));
        }
    });
    handle_key(&mut app, key(KeyCode::Enter));
    assert!(app.modals.is_empty(), "⏎ closes the modal");
    join_test_workers();
    session.join().expect("session thread");
    drain_session_moves(&mut app);
    assert_eq!(last_toast(&app), "session 4242-0: swapping… onto tm-b");
    let moved = crate::live_sessions::get("4242-0").expect("row");
    assert_eq!(moved.current_member.as_deref(), Some("tm-b"));
    assert_eq!(moved.key_generation, Some(1));

    // A relaunch-only session: the command, never a relaunch.
    let ro = crate::testutil::live_row("4242-1", "tm-a").with_executor(
        crate::hot_swap::Executor::RelaunchOnly {
            reason: "fake_links".to_string(),
        },
        None,
    );
    crate::live_sessions::register(&ro).expect("register");
    let _ro_marker = crate::runtime::hold_session_row_marker(
        &crate::profile::ProfileName::from("tm-a"),
        false,
        "4242-1",
    )
    .expect("marker");
    handle_key(&mut app, key(KeyCode::Char('m')));
    let Some(Modal::MoveSession(form)) = app.modals.last() else {
        panic!("the move modal is open");
    };
    let pos = form
        .sessions
        .iter()
        .position(|s| s.sid == "4242-1")
        .expect("the relaunch-only session is offered");
    for _ in 0..pos {
        handle_key(&mut app, key(KeyCode::Down));
    }
    handle_key(&mut app, key(KeyCode::Enter));
    join_test_workers();
    drain_session_moves(&mut app);
    assert_eq!(
        last_toast(&app),
        "session 4242-1: relaunch with 'tollgate switch 4242-1 tm-b --relaunch'"
    );
    assert!(
        crate::live_sessions::get("4242-1")
            .expect("row")
            .intended_member
            .is_none(),
        "nothing is written for a relaunch-only session"
    );

    // The session ended between the pick and ⏎: the request core's refusal is
    // the toast, as a danger.
    handle_key(&mut app, key(KeyCode::Char('m')));
    std::fs::remove_file(
        crate::profile::tollgate_dir()
            .expect("tollgate dir")
            .join("live_sessions/4242-0.json"),
    )
    .expect("the row goes");
    handle_key(&mut app, key(KeyCode::Enter));
    join_test_workers();
    drain_session_moves(&mut app);
    let toast = app.toasts.back().expect("a toast");
    assert_eq!(toast.kind, super::ToastKind::Danger);
    assert!(
        toast
            .body
            .starts_with("session 4242-0: no live session '4242-0'"),
        "{}",
        toast.body
    );
}

// ── the Hermes view (hermes spec §2.2) ───────────────────────────────────────

/// A two-profile Hermes roster with bare homes, written directly.
fn write_hermes_roster_for_tui(names: &[&str]) {
    let dir = crate::profile::tollgate_dir().unwrap();
    std::fs::create_dir_all(&dir).unwrap();
    let mut toml = String::from("schema_version = 1\n");
    for n in names {
        toml.push_str(&format!(
            "[[profiles]]\nname = \"{n}\"\nprovider = \"openrouter\"\nmode = \"account\"\n\
             auth = \"env\"\ncreated_at = \"2026-09-29T00:00:00Z\"\n"
        ));
        std::fs::create_dir_all(dir.join("profiles").join(n).join("hermes-home")).unwrap();
    }
    std::fs::write(dir.join("hermes-profiles.toml"), toml).unwrap();
}

/// Test 50: `c` cycles the four filters, and in the Hermes view ↑↓ step the
/// Hermes rows while Enter and `s` raise M-SWITCH for the row under the
/// cursor, switching nothing; outside the Hermes view the keys act on the
/// claude selection as before.
#[test]
fn tui_filter_cycles_four_states_and_hermes_rows_toast_relaunch() {
    use super::{HarnessFilter, Modal, handle_key};
    let _home = crate::testutil::HomeSandbox::new();
    write_hermes_roster_for_tui(&["herm-a", "herm-b"]);
    let mut app = app_with_unlinked_profiles(vec![crate::testutil::blank_profile(
        &crate::profile::ProfileName::from("a"),
    )]);
    app.tab = Tab::Overview;
    assert_eq!(
        app.hermes_rows
            .iter()
            .map(|r| r.name.as_str())
            .collect::<Vec<_>>(),
        ["herm-a", "herm-b"]
    );
    assert!(
        app.hermes_rows
            .iter()
            .all(|r| !r.live && r.estimate.is_none())
    );

    for want in [
        HarnessFilter::Claude,
        HarnessFilter::Codex,
        HarnessFilter::Hermes,
    ] {
        let before = app.harness_filter;
        handle_key(&mut app, crate::testutil::key(KeyCode::Char('c')));
        assert_eq!(app.harness_filter, before, "the harness key stays hidden");
        app.harness_filter = before.next();
        assert_eq!(app.harness_filter, want);
    }

    handle_key(&mut app, crate::testutil::key(KeyCode::Down));
    assert_eq!(
        app.current_main_item(),
        Some(super::MainItemKind::Hermes(1)),
        "↓ steps the Hermes rows"
    );
    handle_key(&mut app, crate::testutil::key(KeyCode::Enter));
    assert_eq!(
        app.toasts.back().map(|t| t.body.as_str()),
        Some("'herm-b' is a Hermes profile; Hermes switches by relaunch: 'tollgate start herm-b'")
    );
    assert!(app.modals.is_empty(), "enter pushes no switch confirm");
    assert_eq!(app.config().state.active_profile, None);
    handle_key(&mut app, crate::testutil::key(KeyCode::Down));
    assert_eq!(
        app.current_main_item(),
        Some(super::MainItemKind::Hermes(0)),
        "the step wraps"
    );
    handle_key(&mut app, crate::testutil::key(KeyCode::Char('s')));
    assert_eq!(
        app.toasts.back().map(|t| t.body.as_str()),
        Some("'herm-a' is a Hermes profile; Hermes switches by relaunch: 'tollgate start herm-a'")
    );

    handle_key(&mut app, crate::testutil::key(KeyCode::Char('c')));
    assert_eq!(app.harness_filter, HarnessFilter::Hermes);
    app.harness_filter = app.harness_filter.next();
    // A read-only extra must not inherit the prior Hermes row's shortcut.
    let hermes = app
        .main_items()
        .iter()
        .position(|r| matches!(r, super::MainItemKind::Hermes(0)))
        .unwrap();
    app.move_overview_cursor(hermes);
    app.usage_extras = vec![overview_monitor_extra()];
    app.usage_extra_cursor = Some(0);
    app.toasts.clear();
    handle_key(&mut app, crate::testutil::key(KeyCode::Char('s')));
    assert!(
        app.toasts.is_empty(),
        "a selected monitor never acts on the prior Hermes row"
    );
    assert_eq!(app.config().state.active_profile, None);
    app.usage_extra_cursor = None;
    app.move_overview_cursor(0);
    assert_eq!(
        app.harness_filter,
        HarnessFilter::All,
        "four states, then back"
    );
    handle_key(&mut app, crate::testutil::key(KeyCode::Enter));
    assert!(
        matches!(app.modals.last(), Some(Modal::Confirm(_))),
        "outside the Hermes view Enter is the claude switch again"
    );
}

/// Review lens guest-ux #3 / concurrency #6. The `m` modal never decides
/// "already on" from the SERVED member: a B session committed to `tm-b` but
/// still served by `tm-a` can be moved back onto `tm-a`, and the pick goes
/// through the request core (which writes the intent) instead of a toast
/// that does nothing while the session still moves to `tm-b`.
#[test]
fn m_moves_a_committed_but_unserved_session_back_to_the_served_member() {
    use super::{Modal, drain_session_moves, handle_key, join_test_workers};
    use crate::testutil::{api_key_profile, key, write_api_key_profile};
    use ratatui::crossterm::event::KeyCode;
    use std::time::Duration;
    const OR: &str = "https://openrouter.ai/api";

    let _home = crate::testutil::HomeSandbox::new();
    let launch = api_key_profile("tb-a", OR, "sk-a");
    write_api_key_profile(&launch);
    write_api_key_profile(&api_key_profile("tb-b", OR, "sk-b"));
    let config = crate::profile::load_config().expect("load config");
    let target_idx = config
        .profiles
        .iter()
        .position(|p| p.name.as_str() == "tb-a")
        .expect("tb-a is on the roster");
    let mut app = super::App::new(config);
    app.modals.clear();
    app.profile_cursor.set(target_idx);
    let mut row = crate::testutil::live_row("4242-0", "tb-a").with_executor(
        crate::hot_swap::Executor::ApiKey,
        crate::hot_swap::LaunchClass::of(&launch, true),
    );
    row.current_member = Some("tb-b".to_string());
    row.key_generation = Some(1);
    crate::live_sessions::register(&row).expect("register");
    let _markers: Vec<std::fs::File> = ["tb-a", "tb-b"]
        .iter()
        .map(|p| {
            crate::runtime::hold_session_row_marker(
                &crate::profile::ProfileName::from(*p),
                false,
                "4242-0",
            )
            .expect("marker")
        })
        .collect();
    handle_key(&mut app, key(KeyCode::Char('m')));
    let Some(Modal::MoveSession(form)) = app.modals.last() else {
        panic!("the move modal is open");
    };
    assert_eq!(
        form.sessions[0].now_on, "tb-a",
        "served by the launch member"
    );
    let session = std::thread::spawn(|| {
        let deadline = std::time::Instant::now() + Duration::from_secs(5);
        while std::time::Instant::now() < deadline {
            if let Some(intended) =
                crate::live_sessions::get("4242-0").and_then(|r| r.intended_member)
            {
                crate::live_sessions::update_as_session("4242-0", |f| {
                    f.set_current_member(intended);
                    f.bump_key_generation();
                    f.set_committed_at(crate::usage::now_ms());
                })
                .expect("commit");
                return;
            }
            std::thread::sleep(Duration::from_millis(5));
        }
    });
    handle_key(&mut app, key(KeyCode::Enter));
    join_test_workers();
    session.join().expect("session thread");
    drain_session_moves(&mut app);
    let moved = crate::live_sessions::get("4242-0").expect("row");
    assert_eq!(moved.intended_member.as_deref(), Some("tb-a"));
    assert_eq!(moved.current_member.as_deref(), Some("tb-a"));
    assert_eq!(moved.key_generation, Some(2));
    let toast = app
        .toasts
        .back()
        .map(|t| t.body.clone())
        .unwrap_or_default();
    assert_eq!(toast, "session 4242-0: swapping… onto tb-a");
}

// ── #104: startup reconcile flags a current refreshless bearer ──────────────

/// #104: `reconcile_startup` compares the live login against the profile's
/// tollgate-private usage pair (`credentials_diverged`), which requires the
/// refresh token to match. A rolling-token profile's live slot holds the
/// refreshless bearer, so the current bearer still reads as diverged and every
/// launch applies `default_divergence` (discard confirm) or flashes the banner.
/// The live login must be judged against what a switch installs — the
/// sidecar — where an access-token match is no divergence at all.
#[test]
fn repro_104_startup_reconcile_accepts_a_current_rolling_bearer() {
    use crate::profile::{
        AppConfig, AppState, ClaudeCredentials, OAuthToken, Profile, ProfileName, save_profile,
    };
    let _home = crate::testutil::HomeSandbox::new();
    let name = "repro-104-rolling";
    let pair = OAuthToken {
        access_token: "at-chain".to_string(),
        refresh_token: Some("rt-chain".to_string()),
        expires_at: Some(crate::usage::now_ms() as i64 + 3_600_000),
        scopes: Some(vec!["user:profile".into(), "user:inference".into()]),
        subscription_type: Some("max".into()),
        ..OAuthToken::default_extra()
    };
    let mut profile = Profile::new(name.to_string(), None, None);
    profile.rolling_token = true;
    profile.credentials = Some(ClaudeCredentials {
        claude_ai_oauth: Some(pair.clone()),
    });
    save_profile(&profile).expect("save profile");
    // The sidecar is the chain's refreshless projection: the SAME access token.
    crate::claude::stamp_rolling_token(&ProfileName::from(name), &pair).expect("stamp");
    let claude_dir = crate::profile::claude_dir().expect("claude dir");
    std::fs::create_dir_all(&claude_dir).expect("mkdir");
    // Typed fixture: no added line spells a JSON credential key (the
    // pre-commit secret scan refuses that shape outright).
    let live = ClaudeCredentials {
        claude_ai_oauth: Some(OAuthToken {
            access_token: "at-chain".to_string(),
            refresh_token: None,
            expires_at: Some(crate::usage::now_ms() as i64 + 3_600_000),
            scopes: Some(vec!["user:profile".into(), "user:inference".into()]),
            subscription_type: Some("max".into()),
            ..OAuthToken::default_extra()
        }),
    };
    std::fs::write(
        claude_dir.join(".credentials.json"),
        serde_json::to_vec(&live).expect("ser"),
    )
    .expect("write live");
    let state = AppState {
        active_profile: Some(ProfileName::from(name)),
        profiles: vec![ProfileName::from(name)],
        ..AppState::default()
    };
    crate::profile::save_app_state(&state).expect("persist state");
    let mut app = App::new(AppConfig {
        state,
        profiles: vec![profile],
    });
    super::reconcile_startup(&mut app);
    let signal = app.startup_results.try_recv();
    assert!(
        matches!(signal, Ok(crate::usage::StartupSignal::ReconcileDone)),
        "a live slot holding the CURRENT rolling bearer is not a divergence (#104): {signal:?}"
    );
}

/// The same class, wider: a static-mint profile's live slot holds the mint, a
/// DIFFERENT token than the tollgate-private usage pair. The pair-compare reads
/// that as a divergence on every launch too; against the install source it is
/// not one.
#[test]
fn repro_104_startup_reconcile_accepts_a_current_static_mint() {
    use crate::profile::{
        AppConfig, AppState, ClaudeCredentials, OAuthToken, Profile, ProfileName, save_profile,
    };
    let _home = crate::testutil::HomeSandbox::new();
    let name = "repro-104-static";
    let pair = OAuthToken {
        access_token: "at-chain".to_string(),
        refresh_token: Some("rt-chain".to_string()),
        expires_at: Some(crate::usage::now_ms() as i64 + 3_600_000),
        scopes: Some(vec!["user:profile".into(), "user:inference".into()]),
        subscription_type: Some("max".into()),
        ..OAuthToken::default_extra()
    };
    let mut profile = Profile::new(name.to_string(), None, None);
    profile.credentials = Some(ClaudeCredentials {
        claude_ai_oauth: Some(pair),
    });
    save_profile(&profile).expect("save profile");
    crate::claude::write_session_token(
        &ProfileName::from(name),
        "setup-mint-fixture",
        crate::usage::now_ms() as i64,
    )
    .expect("mint");
    let claude_dir = crate::profile::claude_dir().expect("claude dir");
    std::fs::create_dir_all(&claude_dir).expect("mkdir");
    let live = ClaudeCredentials {
        claude_ai_oauth: Some(OAuthToken {
            access_token: "setup-mint-fixture".to_string(),
            refresh_token: None,
            expires_at: Some(crate::usage::now_ms() as i64 + 3_600_000),
            scopes: None,
            subscription_type: None,
            ..OAuthToken::default_extra()
        }),
    };
    std::fs::write(
        claude_dir.join(".credentials.json"),
        serde_json::to_vec(&live).expect("ser"),
    )
    .expect("write live");
    let state = AppState {
        active_profile: Some(ProfileName::from(name)),
        profiles: vec![ProfileName::from(name)],
        ..AppState::default()
    };
    crate::profile::save_app_state(&state).expect("persist state");
    let mut app = App::new(AppConfig {
        state,
        profiles: vec![profile],
    });
    super::reconcile_startup(&mut app);
    let signal = app.startup_results.try_recv();
    assert!(
        matches!(signal, Ok(crate::usage::StartupSignal::ReconcileDone)),
        "a live slot holding the current static mint is not a divergence: {signal:?}"
    );
}

